import java.util.Scanner;

public class Main {
    static final int N = 1000500;
    static final long mod = 1000000007;
    static long[] cycle_counts = new long[N];
    static boolean[] visited = new boolean[N];
    static long[] total = new long[N];

    static long find_cycle_length(long start, long k, long n) {
        long length = 0;
        while (true) {
            if (visited[(int) start]) break;
            visited[(int) start] = true;
            start = (start * k) % n;
            length++;
        }
        return length;
    }

    static long mod_pow(long base, long exp) {
        if (exp == 0) return 1;
        long half = mod_pow(base, exp / 2);
        if (exp % 2 == 0) {
            return (half * half) % mod;
        } else {
            return (base * ((half * half) % mod)) % mod;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(mod_pow(n, n - 1));
            sc.close();
            return;
        }

        for (long i = 0; i < n; i++) {
            if (!visited[(int) i]) {
                long cycle_len = find_cycle_length(i, k, n);
                cycle_counts[(int) cycle_len]++;
            }
        }

        for (long i = 1; i <= n; i++) {
            for (long j = i; j <= n; j += i) {
                if (cycle_counts[(int) j] != 0) {
                    total[(int) j] += cycle_counts[(int) i] * i;
                }
            }
        }

        long result = 1;
        for (long i = 1; i <= n; i++) {
            if (total[(int) i] != 0) {
                result = (result * mod_pow(total[(int) i], cycle_counts[(int) i])) % mod;
            }
        }

        System.out.println(result);
        sc.close();
    }
}
